import { React, useState } from "react";
import cat1 from "./Images/Cats/cat1.png";
import "./App.css";

export default function Cat() {
    const [male, setMale] = useState(0)
    const [female, setFemale] = useState(0)
    return (
        <div className="gallery">
            <div>
                <img src={cat1} alt="cat1" />
            </div>
            <div className="desc">Ginger Cat</div>
            <div>
                M
                <button onClick={() => setMale(Math.max(0, male - 1))}>-</button>{male}
                <button onClick={() => setMale(male + 1)}> +</button>
                F
                <button onClick={() => setFemale(Math.max(0, female - 1))}>-</button>{female}
                <button onClick={() => setFemale(male + 1)}>+</button>
            </div>
        </div>
    )
}
